import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"运行时 (Runtime)","description":"","frontmatter":{},"headers":[],"relativePath":"runtime.md","filePath":"runtime.md","lastUpdated":1669882888000}'),i={name:"runtime.md"};function o(p,e,r,l,d,u){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="运行时-runtime" tabindex="-1">运行时 (Runtime)</h1><hr><p style="font:italic 1em sans-serif;color:#78909C;">此章节待补充或完善...</p><p style="font:italic 1em sans-serif;color:#78909C;">Marked by SuperMonster003 on Oct 31, 2022.</p><hr><h2 id="runtime-requestpermissions-permissions" tabindex="-1">runtime.requestPermissions(permissions)</h2><ul><li><code>permissions</code> {Array} 权限的字符串数组</li></ul><p>动态申请安卓的权限. 例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//请求GPS权限</span></span>
<span class="line"><span>runtime.requestPermissions([&quot;access_fine_location&quot;]);</span></span></code></pre></div><p>尽管安卓有很多权限, 但必须写入Manifest才能动态申请, 为了防止权限的滥用, 目前Auto.js只能额外申请两个权限：</p><ul><li><code>access_fine_location</code> GPS权限</li><li><code>record_audio</code> 录音权限</li></ul><p>您可以通过APK编辑器来增加Auto.js以及Auto.js打包的应用的权限.</p><p>安卓所有的权限列表参见<a href="https://developer.android.com/guide/topics/permissions/overview/" target="_blank" rel="noreferrer">Permissions Overview</a>. （并没有用）</p><h2 id="runtime-loadjar-path" tabindex="-1">runtime.loadJar(path)</h2><ul><li><code>path</code> {string} jar文件路径</li></ul><p>加载目标jar文件, 加载成功后将可以使用该Jar文件的类.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 加载jsoup.jar</span></span>
<span class="line"><span>runtime.loadJar(&quot;./jsoup.jar&quot;);</span></span>
<span class="line"><span>// 使用jsoup解析html</span></span>
<span class="line"><span>importClass(org.jsoup.Jsoup);</span></span>
<span class="line"><span>log(Jsoup.parse(files.read(&quot;./test.html&quot;)));</span></span></code></pre></div><p>(jsoup是一个Java实现的解析Html DOM的库, 可以在<a href="https://jsoup.org/download/" target="_blank" rel="noreferrer">Jsoup</a>下载/)</p><h2 id="runtime-loaddex-path" tabindex="-1">runtime.loadDex(path)</h2><ul><li><code>path</code> {string} dex文件路径</li></ul><p>加载目标dex文件, 加载成功后将可以使用该dex文件的类.</p><p>因为加载jar实际上是把jar转换为dex再加载的, 因此加载dex文件会比jar文件快得多. 可以使用Android SDK的build tools的dx工具把jar转换为dex.</p>`,22)])])}const h=s(i,[["render",o]]);export{m as __pageData,h as default};
